python - <<'PY'
import json
from collections import Counter, defaultdict
path='/tmp/mdblueprint-econcslib-lint-20260615T143626Z.json'
findings=json.load(open(path))
print('total', len(findings))
print('by_code')
for code,count in Counter(f['code'] for f in findings).most_common():
    print(code, count)
print('\\nby_level')
for level,count in Counter(f['level'] for f in findings).most_common():
    print(level, count)
print('\\nwarning codes')
for code,count in Counter(f['code'] for f in findings if f['level']=='warning').most_common():
    print(code, count)
print('\\nprose dep top node')
c=Counter(f['node_id'] for f in findings if f['code']=='LINT_PROSE_DEP')
for nid,count in c.most_common(20): print(count, nid)
print('\\nredundant dep top node')
c=Counter(f['node_id'] for f in findings if f['code']=='LINT_REDUNDANT_DEP')
for nid,count in c.most_common(20): print(count, nid)
print('\\nfuzzy dup')
for f in findings:
    if f['code']=='LINT_FUZZY_DUP': print(f['node_id'], '->', f['related'], f['message'])
print('\\nstaged overlap')
for f in findings:
    if f['code']=='LINT_STAGED_OVERLAP': print(f['node_id'], '->', f['related'], f['message'])
print('\\ntopic cycle')
for f in findings:
    if f['code']=='LINT_TOPIC_CYCLE': print(f['message'])
print('\\ntopic lean top roots/messages sample')
for f in [x for x in findings if x['code']=='LINT_TOPIC_LEAN_ALIGNMENT'][:40]: print(f['node_id'], '->', f['related'][0])
PY"

