      "id": "game_theory.strategic_game.zero_sum.maximin_minimax",
      "title": "Maximin and Minimax Values",
      "kind": "definition",
      "status": "formalized",
      "evidence": "admitted",
      "home_topic": "game_theory.zero_sum",
      "topics": [
