      "id": "game_theory.strategic_game.zero_sum.maximin_le_minimax",
      "title": "Maximin is Bounded by Minimax",
      "kind": "lemma",
      "status": "proved",
      "evidence": "admitted",
      "home_topic": "game_theory.zero_sum",
      "topics": [
        "game_theory.zero_sum",
        "game_theory.zero_sum.minimax"
      ],
      "uses": [
